# The script for generating the figures related to the AR6 benchmarking. 
# This assumes that the benchmarking data has already been generated by 
# the hector run archive. 


# 0. Set Up --------------------------------------------------------------------
library(dplyr)
library(ggplot2)
library(tidyr)

c("data/AR6_benchmarks-CMP406.csv",
"data/AR6_benchmarks-V3.2.0.csv",
"data/AR6_benchmarks-V3.5.0.csv",
"data/ar6.csv",
"data/ar6_scms.csv") -> 
  files

# Make sure that all the files exist, if not then will need make 
# sure copies are moved into the correct directory. 
stopifnot(file.exists(files))


lapply(files, read.csv) %>%  
  bind_rows() %>% 
  # exclude any future scenarios since those are not relevant to the 
  # gcam hector analysis. 
  filter(!grepl(x = scenario, pattern = "ssp")) %>% 
  mutate(variable = tolower(variable)) -> 
  data


# split the data into hector, scms, ar6 ranges.
data %>% 
  filter(is.na(source)) %>% 
  filter(version %in% c("CMP406", "3.2.0")) %>% 
  mutate(version = ifelse(version == "CMP406", "new", "old")) -> 
  HECTOR_DATA

data %>% 
  filter(source == "ar6") -> 
  AR6_RANGE

data %>% 
  filter(! source %in% c("ar6", NA)) -> 
  AR6_SCMS


# 1. Helper Functions ----------------------------------------------------------
# helper function to quickly save and plots 
# Args 
#   plot: ggplot object
#   name: str name of the file 
#   type: .png, indicates the type of file to save 
#   WIDTH/HEIGHT: control the size of the plot 
# Returns: writes the plot to disk
my_ggsave <- function(plot, name, type = ".png", WIDTH = 6, HEIGHT = 4){
  
  fname <- file.path("figs", paste0(name, type))
  ggsave(plot, filename = fname, width = WIDTH, height = HEIGHT)
  
}


theme_set(theme_bw() + theme(legend.title = element_blank()))


# Quick plotting function to take a look at results... 
# Args: 
#   VARS: vector of the variables to plot 
# Returns a ggplot object
quick_plot <- function(VARS, 
                       JW = 0.15, 
                       ar6_scms = AR6_SCMS, 
                       ar6_range = AR6_RANGE,
                       hector_data = HECTOR_DATA){
  
  # Set up colors -- if more than three versions of hector are contirbuting
  # vs <- unique(hector_data$version)
  # num <- length(unique(vs))
  # selected_colors <- hue_pal()(num)
  
  # colors are consistent with the other cmp figures
  selected_colors <- c("old" = "#F8766D", "new" = "#00BFC4")
  
  COLORS <- selected_colors
  #names(COLORS) <- unique(vs)
  monotone <- "darkgrey"
  COLORS <- c(COLORS, "obs" = "black", "ipcc ar6 mean & range" = "black", 
              "scms from ar6" = "grey", "FaIRv1.6.2" = monotone, "MAGICC7" = monotone,
              "CICERO" = monotone, "OSCARv3.1.1" = monotone)
  
  COLORS.BENCHMARKS <- COLORS
  
  
  ar6_range %>% 
    filter(variable %in% VARS) -> 
    arg_range
  
  hector_data %>% 
    filter(variable %in% VARS) -> 
    hec_to_plot
  
  ar6_scms %>% 
    filter(variable %in% VARS) -> 
    scms_to_plot
  
  ggplot() + 
    geom_errorbar(data = arg_range,
                  aes(variable, ymin = min, ymax = max, color = "ipcc ar6 mean & range"),
                  width=.2, alpha = 0.5) +
    geom_point(data = arg_range, aes(variable, value, color = "ipcc ar6 mean & range"), shape = 4, size = 2) +
    geom_point(data = hec_to_plot, aes(variable, value, color = version),
               position = position_jitter(height = 0, width = 0)) + 
    geom_point(data = scms_to_plot, aes(variable, value, color = source),
               shape = 4, position = position_jitter(height = 0, width = JW)) + 
    scale_color_manual(values = COLORS.BENCHMARKS)  -> 
    plot; plot
  
  return(plot)
  
}





# 2. Plots ----------------------------------------------------------------

quick_plot(c("tcre", "tcr")) +
  labs(title = "TCRE & TCR", y = NULL, x = NULL) -> 
  plot; plot 
my_ggsave(plot, name = "ar6_tcre_tcr")

quick_plot(c("hist. warming", "ohc")) +
  labs(title = "Historical", y = NULL, x = NULL) + 
  facet_wrap("variable", scales = "free") -> 
  plot; plot
my_ggsave(plot, name = "ar6_his_warm")

quick_plot(c("rf_ch4", "wmghg rf", "total aerosol rf")) +
  labs(title = "Historical Forcing", y = NULL, x = NULL) + 
  facet_wrap("variable", scales = "free") -> 
  plot; plot
my_ggsave(plot, name = "ar6_hist_rf")


